async function standalone(config){if(window.BOOTCONFIG){return '<!doctype html>'+document.documentElement.outerHTML.replace(/<script id="boot-data">[\s\S]*?<\/script>/,()=>`<script id="boot-data">window.BOOTFONT=${JSON.stringify(window.BOOTFONT)};window.BOOTLICENSE=${JSON.stringify(window.BOOTLICENSE).replace(/</g,'\\u003c')};window.BOOTCONFIG=${JSON.stringify(config).replace(/</g,'\\u003c')};</script>`);}const license=await (await fetch('vendor/OFL.txt')).text();const files=['core.js','notation.js','plot.js','export.js','app.js'],libraries=['katex/katex.min.js','jszip.js','docx.js','pdf-lib.js','fontkit.js'];const [html,css,...scripts]=await Promise.all(['index.html','style.css',...files].map(async f=>await (await fetch(f)).text()));const libs=await Promise.all(libraries.map(async f=>await (await fetch('vendor/'+f)).text()));const strip=s=>s.replace(/^import[^\n]*\n/gm,'').replace(/\bexport (?=(?:async )?(?:function|const|let|class))/g,'');const bytes=await fontReady(),base64=window.BOOTFONT??await new Promise(resolve=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.readAsDataURL(new Blob([bytes]));});const mathCss=await (await fetch('vendor/katex/katex.offline.css')).text(),mathLicense=await (await fetch('vendor/katex/LICENSE.txt')).text();const code=scripts.map(strip).join('\n');let result=html.replace('<head>',()=>'<head><!-- KaTeX license\n'+mathLicense.replace(/-->/g,'-- >')+'\n-->').replace('<link rel="stylesheet" href="vendor/katex/katex.min.css">',()=>'<style>'+mathCss+'</style>').replace('<link rel="stylesheet" href="style.css">',()=>'<style>'+css.replace(/@font-face\{[^}]+\}/g,'')+'</style>').replace(/<script[^>]*src=[^>]*><\/script>/g,'');result=result.replace('</body>',()=>libs.map(l=>'<script>'+l.replace(/<\/script/gi,'<\\/script')+'</script>').join('')+`<script id="boot-data">window.BOOTFONT=${JSON.stringify(base64)};window.BOOTLICENSE=${JSON.stringify(license).replace(/</g,'\\u003c')};window.BOOTCONFIG=${JSON.stringify(config).replace(/</g,'\\u003c')};</script><script id="app-code">(function(){\n${code.replace(/<\/script/gi,'<\\/script')}\n})();</script></body>`);return result;}
export async function makeSources(out,meta,observations,include,plots,options,isExample){const zip=new window.JSZip(),config={version:1,mode:out.id,params:out.rawParams,tables:out.rawTables,meta,plotOptions:Array.from(options.entries())};zip.file('本次实验_输入与作图配置.json',JSON.stringify(config,null,2));zip.file('计算结果_完整精度.json',JSON.stringify(out,null,2));for(const t of modes[out.id].tables){if(!out.tables[t.id].length)continue;zip.file('原始数据_'+t.id+'.csv','\uFEFF'+t.cols.join(',')+'\n'+out.rawTables[t.id].trim().split('\n').map(x=>x.trim().split(/[\t,，;；\s]+/).join(',')).join('\n'));}for(const t of out.processed)zip.file('处理结果_'+t.name+'.csv','\uFEFF'+t.headers.join(',')+'\n'+t.rows.map(r=>r.map(v=>v??'').join(',')).join('\n'));plots.forEach((p,i)=>{zip.file(`附图${i+1}.svg`,p.svg);zip.file(`附图${i+1}_300dpi.png`,p.png);});zip.file('离线复算与重新作图.html',await standalone(config));zip.file('字体许可证_OFL.txt',window.BOOTLICENSE??await (await fetch('vendor/OFL.txt')).text());zip.file('使用说明.txt','打开“离线复算与重新作图.html”，已填入本次数据，可以修改后复算和下载。所有库与中文字体已内嵌；无需联网。CSV保留原始读数，JSON保存完整计算精度；SVG可继续编辑，PNG按300dpi写入元数据。Excel原生图表可修改图旁数据；复杂模型和插值请回网页重新计算。\n字体采用Noto Sans SC，SIL OFL许可证。');const [word,xlsx,pdf]=await Promise.all([makeWord(out,meta,observations,include,plots,isExample),makeXlsx(out,meta,options,isExample),makePdf(out,meta,observations,include,plots,isExample)]);zip.file('实验数据与图表.docx',word);zip.file('实验数据与可编辑图表.xlsx',xlsx);zip.file('实验数据与图表.pdf',pdf);return zip.generateAsync({type:'uint8array',compression:'DEFLATE'});}
export async function exportArtifact(kind,out,meta,observations,include,options,isExample){const name=baseName(out),plots=await makePlots(out,meta,options);const data=kind==='docx'?await makeWord(out,meta,observations,include,plots,isExample):kind==='xlsx'?await makeXlsx(out,meta,options,isExample):kind==='pdf'?await makePdf(out,meta,observations,include,plots,isExample):await makeSources(out,meta,observations,include,plots,options,isExample);download(data,name+'.'+(kind==='sources'?'zip':kind));return {bytes:data.length,kind};}
